from __future__ import annotations

"""Status codes and errors for the RPC chain, in the style of gRPC.

Only a small slice is modeled. ``DEADLINE_EXCEEDED`` is raised when a hop is
asked to do work but the request's time budget is already gone, and ``CANCELLED``
is used when an upstream hop tears the call down before a downstream hop runs.
"""

from dataclasses import dataclass, field


class StatusCode:
    OK = "OK"
    DEADLINE_EXCEEDED = "DEADLINE_EXCEEDED"
    CANCELLED = "CANCELLED"
    UNAVAILABLE = "UNAVAILABLE"


class RpcError(Exception):
    """Base class for an RPC that did not return OK."""

    code = StatusCode.UNAVAILABLE

    def __init__(self, message: str = "", hop: str = "") -> None:
        super().__init__(message or self.code)
        self.hop = hop
        self.message = message or self.code

    def to_status(self) -> "RpcStatus":
        return RpcStatus(code=self.code, message=self.message, hop=self.hop)


class DeadlineExceeded(RpcError):
    code = StatusCode.DEADLINE_EXCEEDED


class Cancelled(RpcError):
    code = StatusCode.CANCELLED


@dataclass(frozen=True)
class RpcStatus:
    code: str
    message: str = ""
    hop: str = ""

    def is_ok(self) -> bool:
        return self.code == StatusCode.OK

    def is_deadline_exceeded(self) -> bool:
        return self.code == StatusCode.DEADLINE_EXCEEDED

    def is_cancelled(self) -> bool:
        return self.code == StatusCode.CANCELLED


@dataclass
class RpcResult:
    """The outcome of running a hop or a whole chain."""

    status: RpcStatus
    value: object = None
    hops_run: tuple[str, ...] = field(default_factory=tuple)
    finished_at_ms: int = 0

    @property
    def code(self) -> str:
        return self.status.code

    def ok(self) -> bool:
        return self.status.is_ok()

    def deadline_exceeded(self) -> bool:
        return self.status.is_deadline_exceeded()

    def cancelled(self) -> bool:
        return self.status.is_cancelled()

    def ran(self, hop_name: str) -> bool:
        return hop_name in self.hops_run

    def hop_count(self) -> int:
        return len(self.hops_run)


def ok_status(hop: str = "") -> RpcStatus:
    return RpcStatus(code=StatusCode.OK, hop=hop)


def deadline_status(hop: str = "", message: str = "deadline exceeded") -> RpcStatus:
    return RpcStatus(code=StatusCode.DEADLINE_EXCEEDED, message=message, hop=hop)


def cancelled_status(hop: str = "", message: str = "cancelled upstream") -> RpcStatus:
    return RpcStatus(code=StatusCode.CANCELLED, message=message, hop=hop)

