from __future__ import annotations

"""Gateway that runs a request through a chain of hops under one deadline.

A client hands the gateway an overall budget. The gateway builds the root
:class:`CallContext` and calls the head hop. The whole chain shares one virtual
clock, so the gateway can report exactly when the request finished and which
hops actually ran before the deadline (if any) was hit.
"""

from deadline_policy import describe_policy
from rpc_status import (
    Cancelled,
    DeadlineExceeded,
    RpcResult,
    StatusCode,
    cancelled_status,
    deadline_status,
)
from service_hop import ServiceHop, hop_by_name
from virtual_clock import CallContext, VirtualClock, context_with_budget


class Gateway:
    def __init__(self, head: ServiceHop, clock: VirtualClock | None = None) -> None:
        self.head = head
        self.clock = clock if clock is not None else VirtualClock()

    def call(self, budget_ms: int, request_id: str = "req") -> RpcResult:
        """Run the chain under ``budget_ms`` from the clock's current now."""

        context = context_with_budget(self.clock, budget_ms, request_id)
        return self._run(context)

    def call_with_deadline(self, deadline_ms: int, request_id: str = "req") -> RpcResult:
        context = CallContext(
            clock=self.clock,
            deadline_ms=deadline_ms,
            request_id=request_id,
            hop_path=(),
        )
        return self._run(context)

    def _run(self, context: CallContext) -> RpcResult:
        try:
            return self.head.call(context)
        except DeadlineExceeded as exc:
            return RpcResult(
                status=deadline_status(hop=exc.hop, message=exc.message),
                value=None,
                hops_run=_hops_up_to(self.head, exc.hop),
                finished_at_ms=self.clock.now(),
            )
        except Cancelled as exc:
            return RpcResult(
                status=cancelled_status(hop=exc.hop, message=exc.message),
                value=None,
                hops_run=_hops_up_to(self.head, exc.hop),
                finished_at_ms=self.clock.now(),
            )

    def trace(self, budget_ms: int) -> list[dict[str, object]]:
        """Describe the deadline math at each leg without mutating real state.

        Uses a throwaway clock so the gateway's own clock is untouched.
        """

        scratch = VirtualClock(self.clock.now())
        context = context_with_budget(scratch, budget_ms)
        rows: list[dict[str, object]] = []
        node: ServiceHop | None = self.head
        while node is not None and node.downstream is not None:
            rows.append(describe_policy(context, node.downstream.name, node.local_timeout_ms))
            scratch.advance(node.cost_ms)
            from deadline_policy import child_context

            context = child_context(context, node.downstream.name, node.local_timeout_ms)
            node = node.downstream
        return rows


def _hops_up_to(head: ServiceHop, failed_hop: str) -> tuple[str, ...]:
    """Hops that completed their work before ``failed_hop`` failed fast.

    The hop named ``failed_hop`` raised on entry without doing work, so it is
    not counted among the hops that ran.
    """

    names: list[str] = []
    node: ServiceHop | None = head
    while node is not None:
        if node.name == failed_hop:
            break
        names.append(node.name)
        node = node.downstream
    return tuple(names)


def run_chain(head: ServiceHop, clock: VirtualClock, budget_ms: int) -> RpcResult:
    """Convenience: build a gateway and run one request."""

    return Gateway(head, clock).call(budget_ms)


def finished_within_budget(result: RpcResult, deadline_ms: int) -> bool:
    """Whether the request finished at or before the original deadline."""

    return result.ok() and result.finished_at_ms <= deadline_ms


def overran_by_ms(result: RpcResult, deadline_ms: int) -> int:
    """How far past the deadline the request actually ran (0 if within)."""

    return max(0, result.finished_at_ms - deadline_ms)


def deepest_hop_run(result: RpcResult) -> str | None:
    return result.hops_run[-1] if result.hops_run else None


def hops_after(head: ServiceHop, name: str) -> list[str]:
    node = hop_by_name(head, name)
    if node is None:
        return []
    out: list[str] = []
    node = node.downstream
    while node is not None:
        out.append(node.name)
        node = node.downstream
    return out

