from __future__ import annotations

"""A single hop in the RPC chain.

A hop does some local work (which costs a fixed number of milliseconds on the
virtual clock) and may call exactly one downstream hop. Before doing its own
work, a hop must check the request deadline: if the budget is already gone, it
fails fast with ``DEADLINE_EXCEEDED`` and does not spend any clock time.

The hop is configured with:
  * ``name`` for tracing,
  * ``cost_ms`` it spends on its own work,
  * ``local_timeout_ms`` it would allow a downstream call in isolation.
"""

from deadline_policy import child_context, deadline_already_passed, has_budget_for
from rpc_status import (
    DeadlineExceeded,
    RpcResult,
    RpcStatus,
    StatusCode,
    deadline_status,
    ok_status,
)
from virtual_clock import CallContext


class ServiceHop:
    def __init__(
        self,
        name: str,
        cost_ms: int,
        local_timeout_ms: int = 5_000,
        downstream: "ServiceHop | None" = None,
    ) -> None:
        if cost_ms < 0:
            raise ValueError("cost_ms must be non-negative")
        self.name = name
        self.cost_ms = cost_ms
        self.local_timeout_ms = local_timeout_ms
        self.downstream = downstream
        self.invocations = 0
        self.work_done = 0

    def then(self, downstream: "ServiceHop") -> "ServiceHop":
        """Attach the next hop and return it for chaining."""

        self.downstream = downstream
        return downstream

    def _do_local_work(self, context: CallContext) -> None:
        """Spend this hop's cost on the shared clock."""

        context.clock.advance(self.cost_ms)
        self.work_done += 1

    def call(self, context: CallContext) -> RpcResult:
        """Serve a request: check the deadline, work, then call downstream."""

        self.invocations += 1

        if deadline_already_passed(context):
            raise DeadlineExceeded("deadline already exceeded on entry", hop=self.name)

        if not has_budget_for(context, self.cost_ms):
            raise DeadlineExceeded("not enough budget left for hop work", hop=self.name)

        self._do_local_work(context)

        if self.downstream is None:
            return RpcResult(
                status=ok_status(self.name),
                value={"hop": self.name, "leaf": True},
                hops_run=(self.name,),
                finished_at_ms=context.clock.now(),
            )

        downstream_ctx = child_context(context, self.downstream.name, self.local_timeout_ms)
        result = self.downstream.call(downstream_ctx)
        return RpcResult(
            status=result.status,
            value=result.value,
            hops_run=(self.name,) + result.hops_run,
            finished_at_ms=context.clock.now(),
        )

    def try_call(self, context: CallContext) -> RpcResult:
        """Like :meth:`call`, but convert a deadline failure into a result."""

        try:
            return self.call(context)
        except DeadlineExceeded as exc:
            return RpcResult(
                status=deadline_status(hop=exc.hop, message=exc.message),
                value=None,
                hops_run=context.hop_path + (self.name,),
                finished_at_ms=context.clock.now(),
            )

    def chain_names(self) -> list[str]:
        names = [self.name]
        node = self.downstream
        while node is not None:
            names.append(node.name)
            node = node.downstream
        return names

    def chain_length(self) -> int:
        return len(self.chain_names())

    def total_cost_ms(self) -> int:
        total = 0
        node: "ServiceHop | None" = self
        while node is not None:
            total += node.cost_ms
            node = node.downstream
        return total

    def reset_counters(self) -> None:
        node: "ServiceHop | None" = self
        while node is not None:
            node.invocations = 0
            node.work_done = 0
            node = node.downstream


def build_chain(specs: list[tuple[str, int, int]]) -> ServiceHop:
    """Build a chain from ``(name, cost_ms, local_timeout_ms)`` tuples.

    Returns the head hop. Each hop's ``downstream`` is the next in the list.
    """

    if not specs:
        raise ValueError("need at least one hop")
    hops = [
        ServiceHop(name=name, cost_ms=cost, local_timeout_ms=timeout)
        for name, cost, timeout in specs
    ]
    for upstream, downstream in zip(hops, hops[1:]):
        upstream.downstream = downstream
    return hops[0]


def hop_by_name(head: ServiceHop, name: str) -> ServiceHop | None:
    node: ServiceHop | None = head
    while node is not None:
        if node.name == name:
            return node
        node = node.downstream
    return None

