from __future__ import annotations

"""Deterministic clock and request context for a chain of RPC hops.

There is no real time anywhere in this kata. A ``VirtualClock`` holds a single
integer "now" in milliseconds. A hop advances it by a fixed cost when it does
work. Tests can read the clock to assert exactly how far the chain ran.

A ``CallContext`` carries the request's overall deadline (an absolute time on
the same clock) down the call path. Every hop reads the context to learn how
much budget is left before the caller gives up.
"""

from dataclasses import dataclass


class VirtualClock:
    """A hand-cranked millisecond clock. Nothing here sleeps."""

    def __init__(self, start_ms: int = 0) -> None:
        if start_ms < 0:
            raise ValueError("start_ms must be non-negative")
        self._now = int(start_ms)
        self._advances = 0

    def now(self) -> int:
        return self._now

    def advance(self, delta_ms: int) -> int:
        """Move the clock forward by ``delta_ms`` and return the new now."""

        if delta_ms < 0:
            raise ValueError("cannot move the clock backwards")
        self._now += int(delta_ms)
        self._advances += 1
        return self._now

    def advance_count(self) -> int:
        """How many times the clock was cranked. Useful to count work done."""

        return self._advances

    def reset(self, start_ms: int = 0) -> None:
        self._now = int(start_ms)
        self._advances = 0


@dataclass(frozen=True)
class CallContext:
    """What a hop knows about the request it is serving.

    ``deadline_ms`` is an absolute point on the shared clock. When the clock
    reaches it, the caller has stopped waiting. ``request_id`` and ``hop_path``
    are carried for tracing only.
    """

    clock: VirtualClock
    deadline_ms: int
    request_id: str = "req"
    hop_path: tuple[str, ...] = ()

    def remaining_ms(self) -> int:
        """Budget left before the deadline, never negative."""

        return max(0, self.deadline_ms - self.clock.now())

    def raw_remaining_ms(self) -> int:
        """Budget left, allowed to go negative once the deadline passes."""

        return self.deadline_ms - self.clock.now()

    def is_expired(self) -> bool:
